__NUXT_JSONP__("/de/feature", (function(a){return {data:[{details:{slug:"de",pageTitle:"5 Charakteristiken vom Mentor Language Institute | Mentor Language Institute",pageDescription:"Wir haben seit unserer Eröffnung mehr als 17,000 Studenten geholfen ihr Englisch zu verbessern.",section1:{title:"Warum MLI?",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fmli-mentor.jpg"},section2:{title:"5 Charakteristiken vom Mentor Language Institute",description:["Wir haben seit unserer Eröffnung mehr als 17,000 Studenten geholfen ihr Englisch zu verbessern. Warum wählen Studenten MLI, obwohl es doch so viele andere Englisch Sprachschulen in Los Angeles gibt? Wir haben eine Umfrage bei MLI Studenten gemacht und du findest ihre Antworten weiter unten."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fsurvey.jpg",notes:"Umfragezeitraum : Januar bis Juni 2017 mit 342 Studenten"},section3:[{title:"Nr.1 : Erschwinglicher Preis",subtitle:"Großartiger Preis! Ab $209 pro Woche. Nachmittagskurse sind 40 % günstiger als Vormittagskurse!",description:["Der Nummer 1 Grund für Studenten MLI als Schule zu wählen, ist die Erschwinglichkeit.","Je länger du unsere Schule besuchst, desto günstiger ist die Studiengebühr. Wenn du dich für 1 Monat (4 Wochen) anmeldest, beträgt die Studiengebühr $1,220 = \u003Cb\u003E$305 pro Woche\u003C\u002Fb\u003E. Das ist schon preiswert für LA. Aber wenn du dich für 48 Wochen anmeldest, beträgt die Studiengebühr nur $10,032 = \u003Cspan style=\"color: #ff0000; font-weight: bold;\"\u003E$209 pro Woche\u003C\u002Fspan\u003E. Vergleiche unsere Preise mit denen anderer Schulen."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002FPRICE_CHART_WEB_JAN06.jpg",links:[{icon:a,text:"Details über die Studiengebühr",link:"\u002Fde\u002Fprice"}]},{title:"Nr.2 : Grossartiger Standort",subtitle:"Westwood & Hollywood: populäre Gegenden in Los Angeles",description:["Wir haben unsere Standorte in grossartigen und populären Gegenden von Los Angeles, \u003Cb\u003EWestwood\u003C\u002Fb\u003E und \u003Cb\u003EHollywood\u003C\u002Fb\u003E. Von hier aus können Studenten bekannte Orte wie Santa Monica und Downtown LA einfach erreichen."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgreat-location.jpg",locations:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fwestwood-campus.jpg",label:"Westwood Campus"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fhollywood-campus.jpg",label:"Hollywood Campus"}],links:[{icon:a,text:"Details über den Westwood Campus",link:"\u002Fde\u002Fwestwood"},{icon:a,text:"Details über den Hollywood Campus",link:"\u002Fde\u002Fhollywood"}]},{title:"Nr.3 : Vielzahl von Hochschul-Vorbereitungskursen",subtitle:"Viele Studenten wechseln später an die UCLA oder das Santa Monica College, nachdem sie an der MLI studiert haben.",description:["Wir bieten beliebte Test-Vorbereitungsprogramme wie TOEFL®, IELTS™ an. Viele Studenten wechseln an die UCLA, das USC oder das Santa Monica College, nachdem sie ihr Test-Vorbereitungsprogramm bei uns abgeschlossen haben."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgoing-to-college.jpg",links:[{icon:a,text:"Details über das Studieren am College",link:"\u002Fde\u002Fgoing-to-college"}]},{title:"Nr.4 : Flexible Stundenpläne",subtitle:"Wir bieten Kurse am Morgen, Nachmittag und Abend an.",description:["\u003Cb\u003EMLI bietet 3 verschiedene Kurszeiten an\u003C\u002Fb\u003E. Studenten können zwischen Kursen am Morgen, Nachmittag und Abend wählen."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fclass-schedule.png",notes:"※Dies ist ein Stundenplan vom Westwood Campus. Wenn du einen Hollywood Campus Stundenplan sehen möchtest, kontaktiere uns bitte."},{title:"Nr.5 : Studentenwohnheim",subtitle:"Unser Partner: US Support Services Inc. bietet die Möglichkeit sich mit Studenten aus aller Welt in unserem Studentenwohnheim auszutauschen.",description:["Unser Partner: U.S. Support Service Inc. arrangiert Aufenthalte in Gastfamilien und in Studentenwohnheimen. Sie bieten über 40 Räume in unseren Studentenwohnheimen an, die jeweils in der Nähe des Campus liegen. Viele Studenten wählen ein Studentenwohnheim, wenn sie das erste Mal in die Staaten kommen."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fdormitory.jpg",links:[{icon:a,text:"Details über Unterkünfte",link:"\u002Fde\u002Fstay"}]}],dir:"\u002Ffeature",path:"\u002Ffeature\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:29.192Z",updatedAt:"2026-03-24T13:34:16.375Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));